INSERT INTO insights (title,source,url,date,summary,tag) VALUES ('Seedance 2.0 定价：不含视频输入46元/百万tokens','新浪财经','https://finance.sina.com.cn/tech/csj/2026-03-05/doc-inhpxspk3221552.shtml?froms=ggmp','2026-03-05','火山引擎公布Seedance 2.0定价：含视频输入28元/百万tokens、不含视频输入46元/百万tokens；720p约“1秒1元”。','算力定价');
INSERT INTO insights (title,source,url,date,summary,tag) VALUES ('Seedance 2.5 发布：单段30秒长叙事，多轮延长','字节跳动Seed官网','https://seed.bytedance.com/zh/blog/one-take-creation-flexible-referencing-introducing-seedance-2-5','2026-07-31','单次视频生成时长由15秒提升至30秒，可在30秒内组织多个逻辑关联镜头，支持精准参考与编辑。','算力定价');
INSERT INTO insights (title,source,url,date,summary,tag) VALUES ('Seedance 2.5 API价格：不含视频输入70元/百万tokens','观点网/凤凰网','https://i.ifeng.com/c/8vOc31ebjTq','2026-08-07','含视频输入42元/百万tokens，不含视频输入70元/百万tokens；单次输入最多30张图片、10段视频、10段音频参考。','算力定价');
INSERT INTO insights (title,source,url,date,summary,tag) VALUES ('Seedance 2.0 Token用量公式：(输入+输出时长)×宽×高×帧率/1024','火山引擎','https://www.volcengine.com/article/2687010','2026-09-11','按Token用量而非次数计费；时长单位为秒，宽高单位为像素，帧率默认24fps。','算力定价');
